function deleteAccountModal(){showModal(`<div class="modal-head"><h2>Delete account</h2><button class="close" data-close-modal aria-label="Close">${svgIcon('close')}</button></div><p>Permanently remove your account, subscriptions and uploaded files from this server. Download a backup first. Your paid Pro subscription will be canceled immediately. This does not issue a refund.</p><form class="form" data-delete-account-form><div data-form-message></div><div class="field"><label>Type your account email</label><input class="input" name="confirmEmail" type="email" autocomplete="off" required></div><div class="field"><label>Current password</label><input class="input" name="password" type="password" autocomplete="current-password" minlength="8" maxlength="128" required></div><button class="btn btn-danger">Permanently delete account</button></form>`);modalRoot.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;runAction(form.querySelector('button'),async()=>{const oldId=state.user.id;await api('/api/account/delete',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});for(const key of ['rr_subscriptions','rr_docs','rr_tip_dismissed','rr_demo_pro','rr_pro_offer_start','rr_draft','rr_setup_hidden','rr_ux_metrics'])browserStore.removeItem(`${key}:${oldId}`);clearIdentity();navigate('/');toast('Account deleted.','success');},form);});}

function changeLanguage(lang){
 const drafts=[...app.querySelectorAll('form')].map(form=>({selector:form.hasAttribute('data-profile-form')?'[data-profile-form]':form.hasAttribute('data-reminder-form')?'[data-reminder-form]':form.hasAttribute('data-password-form')?'[data-password-form]':form.hasAttribute('data-auth-form')?'[data-auth-form]':null,dirty:form.dataset.dirty,fields:[...form.querySelectorAll('input[name],select[name],textarea[name]')].map(el=>({name:el.name,value:el.value,checked:el.checked}))}));
 state.lang=lang;savePreference('rr_lang',lang);render();
 for(const draft of drafts){if(!draft.selector)continue;const form=app.querySelector(draft.selector);if(!form)continue;form.dataset.dirty=draft.dirty||'false';for(const v of draft.fields){const el=[...form.querySelectorAll('[name]')].find(el=>el.name===v.name);if(el){if(el.tagName==='SELECT'){for(const option of el.options)option.selected=option.value===v.value;}else el.value=v.value;if(el.type==='checkbox')el.checked=v.checked;}}}
}
function translateSurface(root){
 if(state.lang==='en')return;
 root.querySelectorAll('option').forEach(option=>{if(!option.hasAttribute('value'))option.value=option.textContent;});
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode())if(!node.parentElement.closest('[data-user-content],script,style,textarea'))node.textContent=translateText(node.textContent,state.lang);
 root.querySelectorAll('[aria-label],[placeholder],[title]').forEach(el=>{for(const attr of ['aria-label','placeholder','title'])if(el.hasAttribute(attr))el.setAttribute(attr,translateText(el.getAttribute(attr),state.lang));});
}
document.addEventListener('click',globalOutsideClick);
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){document.querySelectorAll('.lang-menu.open,.profile-menu.open,.mobile-menu.open').forEach(el=>el.classList.remove('open'));closeSidebar();}
 if(e.key==='Tab'&&modalRoot.firstChild){const els=[...modalRoot.querySelectorAll('button:not(:disabled),a[href],input:not([type="hidden"]):not(:disabled),select:not(:disabled),textarea')].filter(el=>!el.hidden);if(!els.length){e.preventDefault();return;}const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
function closeSidebar(){document.querySelector('.dash-main')?.removeAttribute('inert');document.querySelector('[data-sidebar]')?.classList.remove('open');document.querySelector('[data-sidebar-backdrop]')?.remove();document.querySelector('[data-sidebar-toggle]')?.setAttribute('aria-expanded','false');document.body.classList.remove('sidebar-open');}
function toggleSidebar(){const sidebar=document.querySelector('[data-sidebar]');if(sidebar?.classList.contains('open')){closeSidebar();return;}sidebar?.classList.add('open');document.querySelector('.dash-main')?.setAttribute('inert','');sidebar?.querySelector('a')?.focus();document.body.classList.add('sidebar-open');document.querySelector('[data-sidebar-toggle]')?.setAttribute('aria-expanded','true');const backdrop=document.createElement('button');backdrop.className='sidebar-backdrop';backdrop.dataset.sidebarBackdrop='';backdrop.setAttribute('aria-label','Close navigation');backdrop.addEventListener('click',closeSidebar);app.append(backdrop);}

function trackUX(event,durationMs){const allowed=['add_started','add_completed','edit_started','edit_completed','reminder_opened','review_completed'];if(!state.user||!allowed.includes(event))return;const metrics=storageJson('rr_ux_metrics',{});metrics[event]=(metrics[event]||0)+1;browserStore.setItem(userStorageKey('rr_ux_metrics'),JSON.stringify(metrics));if(state.meta.analyticsEnabled)api('/api/usage',{method:'POST',body:JSON.stringify({event,id:crypto.randomUUID(),durationMs:Number.isFinite(durationMs)?Math.min(86400000,Math.max(0,durationMs)):null})}).catch(()=>{});}
function rememberDraft(form){const data=Object.fromEntries(new FormData(form));data.startedAt=form.dataset.startedAt||String(Date.now());browserStore.setItem(userStorageKey('rr_draft'),JSON.stringify(data));return browserStore.getItem(userStorageKey('rr_draft'))===JSON.stringify(data);}
function welcomeCard(){return `<article class="card focus-card"><span class="eyebrow">Your first renewal</span><h1>Which subscription do you want to remember?</h1><p>Add the service, amount and next payment date. See what is coming before you are charged.</p><button class="btn btn-primary" data-add-sub>Add your first subscription</button><p class="muted">No bank connection required.</p></article>`;}
function nextImportant(){const next=[...state.subscriptions].sort((a,b)=>nextRenewal(a,today()).localeCompare(nextRenewal(b,today())))[0];if(!next)return '';const days=dayDifference(nextRenewal(next,today()),today());return `<article class="card focus-card"><span class="eyebrow">${days>7?'No scheduled payments in the next 7 days':'Next important payment'}</span><h2 data-user-content>${esc(displayName(next))} · ${money(next.price)}</h2><p>${relativeDay(nextRenewal(next,today()))} · ${localDate(nextRenewal(next,today())).toLocaleDateString(locale())}</p><div class="workflow-actions"><button class="btn btn-primary" data-sub-detail="${esc(next.uid)}">View details</button><a class="btn btn-secondary" href="/dashboard/settings#reminders" data-link>${state.settings.emailReminders?'Manage reminders':'Set up reminders'}</a></div></article>`;}
function workflowCards(){const draft=storageJson('rr_draft',null),done=[state.subscriptions.length>0,state.settings.emailVerified,state.settings.emailReminders],hidden=browserStore.getItem(userStorageKey('rr_setup_hidden'))==='true';const archive=state.archived||[];return `${draft?'<article class="card workflow-card"><h2>Finish your draft</h2><p>Saved on this device. No reminders are scheduled yet.</p><button class="btn btn-primary" data-resume-draft>Continue editing</button><button class="btn btn-secondary" data-discard-draft>Discard draft</button></article>':''}${!hidden&&!done.every(Boolean)?`<article class="card workflow-card"><h2>Set up your radar · ${done.filter(Boolean).length}/3</h2><progress max="3" value="${done.filter(Boolean).length}" aria-label="Setup progress"></progress><ol><li>${done[0]?'✓ ':''}Add your first subscription</li><li>${done[1]?'✓ ':''}Verify your email</li><li>${done[2]?'✓ ':''}Enable email reminders</li></ol><a class="btn btn-secondary" href="/dashboard/settings#reminders" data-link>Set up reminders</a><button class="btn btn-ghost" data-hide-setup>Hide checklist</button></article>`:''}${state.subscriptions.length?'<article class="card workflow-card"><h2>A quick subscription review</h2><p>Review up to 3 services. Keep them, check later or archive a cancellation you already completed.</p><button class="btn btn-secondary" data-start-review>Start review</button></article>':''}${archive.length?`<article class="card workflow-card"><h2>Estimated monthly reduction</h2><strong class="impact-value">${money(archive.reduce((sum,s)=>sum+annualValue(s)/12,0))}</strong><p>Based on services you marked as canceled. This is an estimate, not verified savings.</p><button class="btn btn-secondary" data-view-archive>View archived subscriptions</button></article>`:''}`;}
function addedSuccess(item){showModal(`<div class="modal-head"><h2>Subscription added</h2><button class="close" data-close-modal aria-label="Close">${svgIcon('close')}</button></div><p data-user-content>${esc(displayName(item))} · ${money(item.price)}</p><p>${localDate(nextRenewal(item,today())).toLocaleDateString(locale())}</p><p>${state.settings.emailReminders?'Email reminders are enabled.':'Set up reminders to receive an email before renewal.'}</p><a class="btn btn-primary" data-link href="/dashboard/settings#reminders">${state.settings.emailReminders?'Manage reminders':'Set up reminders'}</a><button class="btn btn-secondary" data-add-another>Add another subscription</button>`);modalRoot.querySelector('[data-add-another]').addEventListener('click',addSubscriptionModal);}
function bindWorkflow(root){
 root.querySelector('[data-resume-draft]')?.addEventListener('click',()=>{const d=storageJson('rr_draft',null);if(d){if(d.uid&&!state.subscriptions.some(s=>s.uid===d.uid)){toast('This subscription is no longer active.','error');return;}subscriptionFormModal(d.preset,d.uid||null,d);}});
 root.querySelector('[data-discard-draft]')?.addEventListener('click',()=>{showModal('<h2>Discard draft?</h2><p>This removes only the draft saved on this device.</p><button class="btn btn-secondary" data-close-modal>Keep editing</button><button class="btn btn-danger" data-confirm-discard>Discard draft</button>');modalRoot.querySelector('[data-confirm-discard]').addEventListener('click',()=>{browserStore.removeItem(userStorageKey('rr_draft'));closeModal();render();});});
 root.querySelector('[data-hide-setup]')?.addEventListener('click',()=>{browserStore.setItem(userStorageKey('rr_setup_hidden'),'true');render();});
 root.querySelector('[data-start-review]')?.addEventListener('click',()=>reviewNext());root.querySelector('[data-view-archive]')?.addEventListener('click',archiveModal);
}
function reviewNext(){const queue=state.subscriptions.filter(s=>!s.lastReviewedDate||dayDifference(today(),s.lastReviewedDate)>=30).slice(0,3);if(!queue.length){toast('All subscriptions have been reviewed recently.','success');return;}reviewItem(queue.map(s=>s.uid),0);}
function reviewItem(ids,index){const item=state.subscriptions.find(s=>s.uid===ids[index]);if(!item){trackUX('review_completed');closeModal();render();toast('Review complete.','success');return;}showModal(`<div class="modal-head"><h2>Subscription review · ${index+1}/${ids.length}</h2><button class="close" data-close-modal aria-label="Close">${svgIcon('close')}</button></div><h3 data-user-content>${esc(displayName(item))}</h3><p>${money(item.price)} / ${cycleLabel(item.cycle)}</p><p>Archiving does not cancel anything with your provider. Only confirm after you have canceled the service.</p><div class="workflow-actions"><button class="btn btn-primary" data-review-keep>Keep subscription</button><button class="btn btn-secondary" data-review-later>Check later</button><button class="btn btn-danger" data-review-cancel>Already canceled</button></div>`);
 modalRoot.querySelector('[data-review-keep]').addEventListener('click',e=>runAction(e.currentTarget,async()=>{await saveAccount(state.subscriptions.map(s=>s.uid===item.uid?{...s,lastReviewedDate:today()}:s));reviewItem(ids,index+1);}));
 modalRoot.querySelector('[data-review-later]').addEventListener('click',()=>reviewItem(ids,index+1));
 modalRoot.querySelector('[data-review-cancel]').addEventListener('click',()=>{showModal(`<h2>Archive canceled subscription?</h2><p data-user-content>${esc(displayName(item))}</p><p>Confirm that you have already canceled this service with its provider.</p><button class="btn btn-secondary" data-back-review>Go back</button><button class="btn btn-danger" data-confirm-archive>Confirm cancellation and archive</button>`);modalRoot.querySelector('[data-back-review]').addEventListener('click',()=>reviewItem(ids,index));modalRoot.querySelector('[data-confirm-archive]').addEventListener('click',e=>runAction(e.currentTarget,async()=>{const before=state.archived;state.archived=[...(before||[]),item];try{await saveAccount(state.subscriptions.filter(s=>s.uid!==item.uid));}catch(err){state.archived=before;throw err;}reviewItem(ids,index+1);}));});
}
function archiveModal(){showModal(`<div class="modal-head"><h2>Archived subscriptions</h2><button class="close" data-close-modal aria-label="Close">${svgIcon('close')}</button></div>${state.archived.map(s=>`<div class="archive-row"><strong data-user-content>${esc(displayName(s))}</strong><button class="btn btn-secondary" data-restore="${esc(s.uid)}">Restore tracking</button></div>`).join('')}<p>Restoring tracking does not reactivate a provider subscription.</p>`);modalRoot.querySelectorAll('[data-restore]').forEach(b=>b.addEventListener('click',()=>runAction(b,async()=>{const before=state.archived,item=before.find(s=>s.uid===b.dataset.restore);state.archived=before.filter(s=>s.uid!==item.uid);try{await saveAccount([...state.subscriptions,item]);}catch(err){state.archived=before;throw err;}closeModal();render();toast('Tracking restored. Check the renewal date.','success');})));}

function calendarAgenda(year,month){const list=state.subscriptions.flatMap(s=>monthRenewals(s,year,month).map(date=>({s,date}))).sort((a,b)=>a.date.localeCompare(b.date));return `<article class="card calendar-agenda"><h2>Payments this month</h2>${list.map(({s,date})=>`<div><span>${localDate(date).toLocaleDateString(locale(),{month:'short',day:'numeric'})}</span><strong data-user-content>${esc(displayName(s))}</strong><b>${money(s.price)}</b></div>`).join('')||'<p>No scheduled payments this month.</p>'}</article>`;}
function safeHash(hash){try{return decodeURIComponent(hash.slice(1));}catch{return '';}}
setInterval(()=>refreshAccount(true),15000);
window.addEventListener('focus',()=>refreshAccount(true));
window.addEventListener('online',()=>refreshAccount(true));
let lastRenderedDay=today();
setInterval(()=>{const day=today();if(day!==lastRenderedDay&&!modalRoot.firstChild&&!app.querySelector('form')){lastRenderedDay=day;render();}},60000);
window.addEventListener('popstate',render);
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('[data-sidebar]')?.classList.remove('open');}});
await loadSession();
await loadUserLocalState();
applyTheme();
render();
const billingReturn=new URLSearchParams(location.search);if(state.user&&(billingReturn.has('checkout')||billingReturn.has('billing'))){history.replaceState({},'',location.pathname);if(billingReturn.get('checkout')==='canceled')toast('Checkout canceled.');else{try{await api('/api/billing/refresh',{method:'POST',body:'{}'});await refreshAccount();toast(state.pro?'Pro active':'Payment is still being confirmed. Refresh billing status shortly.');}catch(e){toast(e.message,'error');}}}
